"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[39307],{1461:e=>{e.exports=JSON.parse('{"functions":[{"name":"Initialize","desc":"Wire the run end, the leave payout and the late-join results. Call once,\\nafter `RunStats.Initialize` and `SessionCoordinator.Initialize`.","params":[],"returns":[],"function_type":"static","source":{"line":216,"path":"src/ServerStorage/SharedModules/RunEndService.luau"}}],"properties":[],"types":[],"name":"RunEndService","desc":"Owns the end of a run. On `Signals.OnTrainGameOver` (any reason): the run is\\nover for revives, every living player dies (no respawn), run stats freeze,\\nevery present player is paid their time-scaled coins + EXP and gets the\\nresults packet, and after `RunRewardConfig.RESULTS_SECONDS` everyone still\\nhere goes to the Lobby.\\n\\nA player who leaves with the Leave button before that is paid for their own\\ntime before the teleport (SessionCoordinator leave hook). A rejoin inside\\nthe results window is paid and shown the results; after it, only that player\\nis bounced. Each player is paid at most once per run.\\nSee docs/systems/run-results.md.","realm":["Server"],"source":{"line":18,"path":"src/ServerStorage/SharedModules/RunEndService.luau"}}')}}]);